spec.setup_code:
var C = { ink: "#04204B", sec: "#3D5F91", guide: "#8098BC", blue: "#0B4FC0", warm: "#B4552F", teal: "#138374", vio: "#6A47C2" };
var T = 16;
var RES = [32, 16, 8, 4, 2];
var CH = [64, 128, 256, 512, 1024];
var LAY = [2, 3, 4, 5, 6];
var FR = [1, 0.72, 0.52, 0.38, 0.3];
var RF = [0.86, 0.78, 0.7, 0.62];
var d = 2;

function cl(x) { return x < 0 ? 0 : x > 1 ? 1 : x; }
function sm(x) { x = cl(x); return x * x * (3 - 2 * x); }
function win(t, a, b, f) { return sm((t - a) / f + 0.5) * sm((b - t) / f + 0.5); }

function layout(W, H) {
  var m = Math.max(10, W * 0.02);
  var colW = (W - 2 * m) / 9;
  var S = Math.min(colW * 0.74, 90);
  d = Math.max(2, S * 0.05);
  var half0 = (S + d) / 2;
  var top = 46 + half0;
  var bot = H - 95;
  var step = (bot - top) / 4;
  var st = [];
  for (var k = 0; k < 9; k++) {
    var lv = k <= 4 ? k : 8 - k;
    var sz = S * FR[lv];
    var D = (LAY[lv] - 1) * d;
    var xc = m + colW * (k + 0.5);
    var yc = top + lv * step;
    var half = (sz + D) / 2;
    st.push({ k: k, lv: lv, sz: sz, D: D, xc: xc, yc: yc, half: half, x0: xc - half, y0: yc - half + D,
      col: k < 4 ? C.blue : (k === 4 ? C.teal : C.warm) });
  }
  return st;
}

function fit(ctx, s, maxW, bold) {
  var z = 13;
  ctx.font = (bold ? "bold " : "") + z + "px sans-serif";
  while (z > 11 && ctx.measureText(s).width > maxW) {
    z--;
    ctx.font = (bold ? "bold " : "") + z + "px sans-serif";
  }
}

function arrow(ctx, x1, y1, x2, y2, col, al, lw) {
  ctx.globalAlpha = al; ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = lw;
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  var a = Math.atan2(y2 - y1, x2 - x1), h = 6;
  ctx.beginPath(); ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - h * Math.cos(a - 0.4), y2 - h * Math.sin(a - 0.4));
  ctx.lineTo(x2 - h * Math.cos(a + 0.4), y2 - h * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
}

function stack(ctx, s) {
  var L = LAY[s.lv];
  for (var m = L - 1; m >= 0; m--) {
    var x = s.x0 + m * d, y = s.y0 - m * d;
    ctx.globalAlpha = 1; ctx.fillStyle = "#ffffff"; ctx.fillRect(x, y, s.sz, s.sz);
    if (m === 0) { ctx.globalAlpha = 0.07; ctx.fillStyle = s.col; ctx.fillRect(x, y, s.sz, s.sz); }
    ctx.globalAlpha = m === 0 ? 1 : 0.75; ctx.strokeStyle = s.col; ctx.lineWidth = 1;
    ctx.strokeRect(x + 0.5, y + 0.5, s.sz - 1, s.sz - 1);
  }
  if (s.lv === 0 && s.k === 0) {
    ctx.globalAlpha = 0.45; ctx.fillStyle = C.warm;
    ctx.beginPath(); ctx.arc(s.x0 + 0.62 * s.sz, s.y0 + 0.38 * s.sz, 0.17 * s.sz, 0, 6.2832); ctx.fill();
    ctx.globalAlpha = 0.3; ctx.fillStyle = C.blue;
    ctx.beginPath(); ctx.moveTo(s.x0 + 0.1 * s.sz, s.y0 + 0.9 * s.sz);
    ctx.lineTo(s.x0 + 0.45 * s.sz, s.y0 + 0.55 * s.sz); ctx.lineTo(s.x0 + 0.8 * s.sz, s.y0 + 0.9 * s.sz);
    ctx.closePath(); ctx.fill();
  }
  var n = RES[s.lv], cell = s.sz / n;
  ctx.globalAlpha = 0.12 + 0.4 * cl(cell / 4); ctx.strokeStyle = C.guide; ctx.lineWidth = 0.6;
  ctx.beginPath();
  for (var i = 1; i < n; i++) {
    ctx.moveTo(s.x0 + i * cell, s.y0); ctx.lineTo(s.x0 + i * cell, s.y0 + s.sz);
    ctx.moveTo(s.x0, s.y0 + i * cell); ctx.lineTo(s.x0 + s.sz, s.y0 + i * cell);
  }
  ctx.stroke();
  ctx.globalAlpha = 1;
}

function dot(ctx, x, y, r, col, al) {
  ctx.globalAlpha = 0.25 * al; ctx.fillStyle = col;
  ctx.beginPath(); ctx.arc(x, y, r * 2, 0, 6.2832); ctx.fill();
  ctx.globalAlpha = al;
  ctx.beginPath(); ctx.arc(x, y, r, 0, 6.2832); ctx.fill();
  ctx.globalAlpha = 1;
}

return {
  draw: function (ctx, W, H, time, dt) {
    ctx.globalAlpha = 1;
    ctx.fillStyle = "#ffffff"; ctx.fillRect(0, 0, W, H);
    var t = time % T;
    var st = layout(W, H);
    var wK = win(t, 0.3, 3.8, 0.5), wR = win(t, 3.8, 7.0, 0.5);
    var wF = win(t, 7.0, 11.2, 0.5), wS = win(t, 11.2, 15.5, 0.5);
    var pr = Math.max(3.5, st[0].sz * 0.06);
    ctx.textAlign = "center"; ctx.textBaseline = "alphabetic";

    // path points through stages
    var pts = [], cum = [0], i, k;
    for (k = 0; k < 9; k++) {
      pts.push([st[k].xc - st[k].half, st[k].yc]);
      pts.push([st[k].xc + st[k].half, st[k].yc]);
    }
    for (i = 1; i < pts.length; i++) {
      cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
    }
    var tot = cum[cum.length - 1];
    function at(u) {
      var dd = cl(u) * tot;
      for (var j = 1; j < pts.length; j++) {
        if (dd <= cum[j] || j === pts.length - 1) {
          var f = (dd - cum[j - 1]) / Math.max(1e-6, cum[j] - cum[j - 1]);
          return [pts[j - 1][0] + (pts[j][0] - pts[j - 1][0]) * f, pts[j - 1][1] + (pts[j][1] - pts[j - 1][1]) * f];
        }
      }
      return pts[0];
    }

    // down / up arrows between stages
    for (k = 0; k < 8; k++) {
      arrow(ctx, pts[2 * k + 1][0], pts[2 * k + 1][1], pts[2 * k + 2][0], pts[2 * k + 2][1], C.guide, 0.35 + 0.65 * wF, 1.3);
    }
    // skip connections
    ctx.lineJoin = "round";
    for (var lv = 0; lv < 4; lv++) {
      var en = st[lv], de = st[8 - lv];
      var xa = en.xc + en.half, xb = de.xc - de.half;
      ctx.setLineDash([5, 4]);
      arrow(ctx, xa, en.yc, xb - 5, en.yc, C.vio, 0.3 + 0.7 * wS, 1.5);
      ctx.setLineDash([]);
    }

    for (k = 0; k < 9; k++) stack(ctx, st[k]);

    // flow pulses
    var pF = cl((t - 7.0) / 4.2), q = sm(pF) * 1.1, j, headK = 0;
    if (wF > 0.01) {
      for (k = 0; k < 9; k++) {
        var g = 0;
        for (j = 0; j < 3; j++) {
          var uu = q - j * 0.05;
          if (uu >= 0 && uu <= 1) {
            var mk = (cum[2 * k] + cum[2 * k + 1]) / 2 / tot;
            var dd = (uu - mk) * tot / (st[k].half + 8);
            g = Math.max(g, Math.exp(-dd * dd));
          }
        }
        if (g > 0.02) {
          ctx.globalAlpha = 0.3 * g * wF; ctx.fillStyle = C.blue;
          ctx.fillRect(st[k].x0, st[k].y0, st[k].sz, st[k].sz);
        }
      }
      var bd = 9;
      for (k = 0; k < 9; k++) {
        var dm = Math.abs(cl(q) - (cum[2 * k] + cum[2 * k + 1]) / 2 / tot);
        if (dm < bd) { bd = dm; headK = k; }
      }
      for (j = 0; j < 3; j++) {
        var u2 = q - j * 0.05;
        if (u2 >= 0 && u2 <= 1) { var pp = at(u2); dot(ctx, pp[0], pp[1], pr, C.blue, wF); }
      }
    }

    // kernel phase
    var kx = 0, ky = 0;
    if (wK > 0.01) {
      var s0 = st[0], cell = s0.sz / 32;
      var uK = cl((t - 0.3) / 3.5) * 3, r = Math.min(2, Math.floor(uK)), f = uK - r;
      kx = (r % 2 === 0 ? f : 1 - f) * 29;
      ky = r * 3 + (r < 2 ? 3 * sm((f - 0.88) / 0.12) : 0);
      var ks = Math.max(3 * cell, 7);
      var kpx = s0.x0 + (kx + 1.5) * cell - ks / 2, kpy = s0.y0 + (ky + 1.5) * cell - ks / 2;
      ctx.globalAlpha = 0.25 * wK; ctx.fillStyle = C.warm; ctx.fillRect(kpx, kpy, ks, ks);
      ctx.globalAlpha = wK; ctx.strokeStyle = C.warm; ctx.lineWidth = 1.5; ctx.strokeRect(kpx, kpy, ks, ks);
      var s1 = st[1], c1 = s1.sz / 16, cs = Math.max(c1, 3);
      var ox = s1.x0 + (kx / 2) * c1, oy = s1.y0 + (ky / 2) * c1;
      ctx.globalAlpha = 0.8 * wK; ctx.fillStyle = C.warm; ctx.fillRect(ox, oy, cs, cs);
      ctx.globalAlpha = 0.4 * wK; ctx.strokeStyle = C.warm; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(kpx + ks, kpy + ks / 2); ctx.lineTo(ox, oy + cs / 2); ctx.stroke();
    }

    // receptive field phase
    if (wR > 0.01) {
      var pR = cl((t - 3.8) / 3.2) * 5.2, prev = null;
      var order = [4, 3, 2, 1, 0];
      for (i = 0; i < 5; i++) {
        var sg = order[i] === 4 ? 4 : order[i];
        var s = order[i] === 4 ? st[4] : st[order[i]];
        var rev = sm(pR - i);
        var w = (order[i] === 4 ? s.sz / 2 : RF[order[i]] * s.sz) * rev;
        if (w > 0.5) {
          ctx.globalAlpha = 0.22 * wR; ctx.fillStyle = C.warm; ctx.fillRect(s.x0, s.y0, w, w);
          ctx.globalAlpha = wR; ctx.strokeStyle = C.warm; ctx.lineWidth = 1.6; ctx.strokeRect(s.x0, s.y0, w, w);
          if (prev) {
            ctx.globalAlpha = 0.5 * wR * rev; ctx.lineWidth = 1; ctx.setLineDash([3, 3]);
            ctx.beginPath(); ctx.moveTo(prev[0], prev[1]); ctx.lineTo(s.x0 + w, s.y0 + w); ctx.stroke();
            ctx.setLineDash([]);
          }
          prev = [s.x0 + w, s.y0 + w];
        }
      }
    }

    // skip pulses
    var pS = (t - 11.2) / 4.3, actS = -1;
    if (wS > 0.01) {
      for (lv = 0; lv < 4; lv++) {
        var e2 = st[lv], d2 = st[8 - lv];
        var sp = cl((pS - lv * 0.12) / 0.5), ta = lv * 0.12 + 0.5;
        if (pS - lv * 0.12 > 0) actS = lv;
        var arrived = sm((pS - ta) / 0.08);
        var flash = arrived * (1 - sm((pS - ta - 0.05) / 0.25));
        if (arrived > 0) {
          ctx.globalAlpha = 0.3 * flash * wS; ctx.fillStyle = C.vio; ctx.fillRect(d2.x0, d2.y0, d2.sz, d2.sz);
          ctx.globalAlpha = 0.55 * arrived * wS; ctx.fillRect(d2.x0, d2.y0, Math.max(3, d2.sz * 0.14), d2.sz);
          ctx.globalAlpha = arrived * wS; ctx.strokeStyle = C.vio; ctx.lineWidth = 2;
          ctx.strokeRect(d2.x0, d2.y0, d2.sz, d2.sz);
        }
        if (sp > 0 && sp < 1) {
          var xa2 = e2.xc + e2.half, xb2 = d2.xc - d2.half;
          dot(ctx, xa2 + (xb2 - xa2) * sm(sp), e2.yc, pr, C.vio, wS);
        }
      }
    }
    ctx.globalAlpha = 1;

    // stage labels
    ctx.font = "11px sans-serif";
    for (k = 0; k < 9; k++) {
      var s3 = st[k], ly = s3.yc + s3.half + 12;
      ctx.fillStyle = s3.col;
      if (k === 4) {
        ctx.fillText("bottleneck", s3.xc, ly);
        ctx.fillStyle = C.sec; ctx.fillText(RES[4] + "² · C=" + CH[4], s3.xc, ly + 12);
      } else {
        ctx.fillText(RES[s3.lv] + "²", s3.xc, ly);
        ctx.fillStyle = C.sec; ctx.fillText("C=" + CH[s3.lv], s3.xc, ly + 12);
      }
    }
    ctx.font = "bold 12px sans-serif";
    ctx.fillStyle = C.blue; ctx.fillText("encoder", st[1].xc, H - 70);
    ctx.fillStyle = C.warm; ctx.fillText("decoder", st[7].xc, H - 70);
    ctx.globalAlpha = 0.55 + 0.45 * wS; ctx.fillStyle = C.vio;
    ctx.fillText("skip", W / 2, st[0].yc - 6);
    ctx.globalAlpha = 1;

    // captions
    var caps = ["a 3×3 kernel slides over the map: local patches", "every downsampling doubles how far a cell can see",
      "data flows down for context, then up for detail", "skips carry fine detail straight across"];
    var ws = [wK, wR, wF, wS];
    for (i = 0; i < 4; i++) {
      if (ws[i] > 0.01) {
        fit(ctx, caps[i], W - 16, false);
        ctx.globalAlpha = ws[i]; ctx.fillStyle = C.ink; ctx.fillText(caps[i], W / 2, 20);
      }
    }
    var names = ["encoder 1", "encoder 2", "encoder 3", "encoder 4", "bottleneck", "decoder 4", "decoder 3", "decoder 2", "decoder 1"];
    var det = [
      "kernel at row " + Math.round(ky + 1) + ", col " + Math.round(kx + 1) + " of the 32² map",
      "one bottleneck cell sees most of the 32² input",
      "pulse at " + names[headK] + " · " + RES[st[headK].lv] + "², C=" + CH[st[headK].lv],
      "skip " + (actS + 1) + ": encoder " + (actS + 1) + " features concatenated"
    ];
    for (i = 0; i < 4; i++) {
      if (ws[i] > 0.01) {
        fit(ctx, det[i], W - 16, false);
        ctx.globalAlpha = ws[i]; ctx.fillStyle = C.sec; ctx.fillText(det[i], W / 2, H - 14);
      }
    }
    ctx.globalAlpha = 1;
  }
};
